query:
SELECT status, COUNT(*) as count FROM house_races GROUP BY status ORDER BY status;
SELECT state_code, district, status, called_winner, called_party, pct_reporting, updated_at FROM house_races WHERE state_code IN ('NE','WV') ORDER BY state_code, district;
SELECT state_code, status, called_winner, called_party, pct_reporting, updated_at FROM senate_races WHERE state_code IN ('NE','WV') ORDER BY state_code;
SELECT MAX(updated_at) as last_update FROM house_races;

